import os
import requests

def compare_metric_series(payload, config=None):
    config = config or {}
    api_key = config.get("api_key") or os.environ["DATADOG_API_KEY"]
    app_key = config.get("app_key") or os.environ["DATADOG_APP_KEY"]
    site = config.get("site") or os.environ.get("DATADOG_SITE", "datadoghq.com")
    query = payload["query"]
    from_ts = int(payload["from"])
    to_ts = int(payload["to"])
    resp = requests.get(
        f"https://api.{site}/api/v1/query",
        params={"from": from_ts, "to": to_ts, "query": query},
        headers={
            "DD-API-KEY": api_key,
            "DD-APPLICATION-KEY": app_key,
            "Accept": "application/json",
        },
        timeout=config.get("timeout", 30),
    )
    resp.raise_for_status()
    data = resp.json()
    series = data.get("series", [])
    result = {
        "from": from_ts,
        "to": to_ts,
        "query": query,
        "series": [],
    }
    for s in series[:2]:
        pointlist = s.get("pointlist") or []
        cleaned = [(int(ts), val) for ts, val in pointlist if val is not None]
        values = [val for _, val in cleaned]
        result["series"].append(
            {
                "metric": s.get("metric"),
                "scope": s.get("scope"),
                "tag_set": s.get("tag_set", []),
                "expression": s.get("expression"),
                "aggr": s.get("aggr"),
                "unit": s.get("unit"),
                "points": cleaned,
                "summary": {
                    "count": len(values),
                    "avg": (sum(values) / len(values)) if values else None,
                    "min": min(values) if values else None,
                    "max": max(values) if values else None,
                    "latest": values[-1] if values else None,
                },
            }
        )
    if len(result["series"]) == 2:
        a_vals = {ts: val for ts, val in result["series"][0]["points"]}
        b_vals = {ts: val for ts, val in result["series"][1]["points"]}
        common_ts = sorted(set(a_vals) & set(b_vals))
        diffs = [{"ts": ts, "a": a_vals[ts], "b": b_vals[ts], "delta": a_vals[ts] - b_vals[ts]} for ts in common_ts]
        delta_values = [d["delta"] for d in diffs]
        result["comparison"] = {
            "aligned_points": len(common_ts),
            "diffs": diffs,
            "summary": {
                "avg_delta": (sum(delta_values) / len(delta_values)) if delta_values else None,
                "min_delta": min(delta_values) if delta_values else None,
                "max_delta": max(delta_values) if delta_values else None,
                "latest_delta": delta_values[-1] if delta_values else None,
            },
        }
    else:
        result["comparison"] = None
    return result
